def generate_powershell_config(no_cmd, cmd_prefix, hook):
    if no_cmd:
        return '''# =============================================================================
#
# Utility functions for zoxide.
#

function __zoxide_pwd {
    Get-Location
}

function __zoxide_cd {
    Set-Location -LiteralPath $args
}

# =============================================================================
#
# Hook configuration for zoxide.
#

$__zoxide_oldpwd = (__zoxide_pwd)

function __zoxide_hook {
    $retval = $LASTEXITCODE
    $pwd_tmp = (__zoxide_pwd)
    if ($__zoxide_oldpwd -ne $pwd_tmp) {
        $__zoxide_oldpwd = $pwd_tmp
        builtin zoxide add -- $__zoxide_oldpwd
    }
    return $retval
}

# Initialize hook.
if (-not $env:PROMPT_COMMAND -or $env:PROMPT_COMMAND -notmatch "__zoxide_hook") {
    if ($env:PROMPT_COMMAND -match "declare -a") {
        $env:PROMPT_COMMAND = "$env:PROMPT_COMMAND __zoxide_hook"
    } else {
        $env:PROMPT_COMMAND = "__zoxide_hook"
    }
}

# Report common issues.
function __zoxide_doctor {
    if ($env::_ZO_DOCTOR -eq 0) { return 0 }
    if ($env:PROMPT_COMMAND -match "__zoxide_hook") { return 0 }
    if ($env::__vsc_original_prompt_command -match "__zoxide_hook") { return 0 }

    $env::_ZO_DOCTOR = 0
    Write-Host "zoxide: detected a possible configuration issue."
    Write-Host "Please ensure that zoxide is initialized right at the end of your shell configuration file (usually ~/.profile)."
    Write-Host ""
    Write-Host "If the issue persists, consider filing an issue at:"
    Write-Host "https://github.com/ajeetdsouza/zoxide/issues"
    Write-Host ""
    Write-Host "Disable this message by setting _ZO_DOCTOR=0."
    Write-Host ""
}

# =============================================================================
#
# When using zoxide with --no-cmd, alias these internal functions as desired.
#

$__zoxide_z_prefix = 'z#'

function __zoxide_z {
    __zoxide_doctor

    if ($args.Count -eq 0) {
        __zoxide_cd ~
    } elseif ($args.Count -eq 1 -and $args[0] -eq "-") {
        __zoxide_cd $env:OLDPWD
    } elseif ($args.Count -eq 1 -and (Test-Path -LiteralPath $args[0])) {
        __zoxide_cd $args[0]
    } elseif ($args.Count -eq 2 -and $args[0] -eq "--") {
        __zoxide_cd $args[1]
    } elseif ($args[-1] -match "${__zoxide_z_prefix}.*") {
        $result = $args[-1]
        __zoxide_cd $result.Substring($result.Length - [int]$result.Length - [int]${__zoxide_z_prefix}.Length)
    } else {
        $result = (builtin zoxide query --exclude "$(__zoxide_pwd)" -- $args)
        __zoxide_cd $result
    }
}

function __zoxide_zi {
    __zoxide_doctor
    $result = (builtin zoxide query --interactive -- $args)
    __zoxide_cd $result
}

# =============================================================================
#
# Commands for zoxide. Disable these using --no-cmd.
#

z {
    __zoxide_z $args
}

zi {
    __zoxide_zi $args
}
'''
    else:
        return '''# =============================================================================
#
# Utility functions for zoxide.
#

function __zoxide_pwd {
    Get-Location
}

function __zoxide_cd {
    Set-Location -LiteralPath $args
}

# =============================================================================
#
# Hook configuration for zoxide.
#

$__zoxide_oldpwd = (__zoxide_pwd)

function __zoxide_hook {
    $retval = $LASTEXITCODE
    $pwd_tmp = (__zoxide_pwd)
    if ($__zoxide_oldpwd -ne $pwd_tmp) {
        $__zoxide_oldpwd = $pwd_tmp
        builtin zoxide add -- $__zoxide_oldpwd
    }
    return $retval
}

# Initialize hook.
if (-not $env:PROMPT_COMMAND -or $env:PROMPT_COMMAND -notmatch "__zoxide_hook") {
    if ($env:PROMPT_COMMAND -match "declare -a") {
        $env:PROMPT_COMMAND = "$env:PROMPT_COMMAND __zoxide_hook"
    } else {
